INSERT INTO changelog (title, body, created_at) VALUES
('Джері бачить картинки',
'Новий інструмент view_images: Джері сам відкриває і розглядає фото з Telegram-групи клієнта (конкретні або N останніх) і креативи Meta-реклами — описує, оцінює, порівнює, радить. Просто спитай: «глянь останні креативи в групі» або «оціни креатив такий-то». До 8 картинок за раз, кожна коштує токенів. Тумблер — Налаштування → «Можливості» → «Дивитись картинки». Фото понад 20 МБ (ліміт Telegram для бота) і понад 4.5 МБ (ліміт API) він не відкриє — скаже про це.',
'2026-11-01 10:00:00');
